# frozen_string_literal: true

# Builds aas-vectors.json from the passports named below, using AasView and
# DppRepresentation of this repository:
#
#   ruby -Iapp/lib spec/fixtures/aas-vectors/generate.rb
#
# The vectors are the specification of the AAS view (docs/AAS.md):
# spec/lib/aas_vectors_spec.rb holds AasView to them, and
# spec/lib/aas_conformance_spec.rb hands every environment to the AAS test
# engines of the IDTA. A custodian that carries a copy of AasView runs the same
# vectors. Regenerating is a deliberate change of that specification.
#
#   source-battery.json  the battery example of the DPP Manager (product type
#                        DppBattery, invented values), as its transformation
#                        writes it
#   source-lamp.json     the LED lamp example of the DPP Manager
#   source-en18223.json  every class of data element (representation vectors)
#   compressed           the same passport in the compressed representation
require "json"
require "uri"
require "aas_view"
require "dpp_representation"

DIR = __dir__

def read(path) = JSON.parse(File.read(File.join(DIR, path)))

sources = {
  "battery" => read("source-battery.json"),
  "lamp" => read("source-lamp.json"),
  "en18223" => read("../representation-vectors/source-en18223.json")
}
sources["compressed"] = DppRepresentation.passport(sources["en18223"], "compressed")

cases = sources.map do |name, passport|
  base = "https://dpp.example.org/dpp/v1/dpps/#{URI.encode_www_form_component(passport['digitalProductPassportId'])}"
  aas_id = "#{base}/aas"
  source = { "sourcePassport" => "#{base}?representation=full", "signatureState" => "none",
             "payloadHash" => "sha256-example" }
  { "name" => name, "passport" => passport, "aasId" => aas_id, "source" => source,
    "environment" => AasView.environment(passport, aas_id: aas_id, source: source) }
end

vectors = {
  "description" => "EN 18223 passport -> AAS V3.0 environment (docs/AAS.md); generated by generate.rb, see there",
  "aasVersion" => AasView::VERSION,
  "cases" => cases
}

File.write(File.join(DIR, "aas-vectors.json"), "#{JSON.pretty_generate(vectors)}\n")
puts "aas-vectors.json: #{cases.size} cases"
